 $db->exec("DELETE FROM family_migrations WHERE migration_key='milestone-albums-v1'");initializeFamilyAlbums($db);$albums=familyAlbums($db);verifyAlbum(count($albums)===1,'One migrated album');$album=$albums[0];verifyAlbum($album['title']==='Christmas 2024'&&$album['date']==='2024-12-25'&&$album['milestoneId']==='event','Migration name/date/link');verifyAlbum($album['photos']===[$photo,$photo],'Duplicate occurrences/order');$rows=familyMediaRows($db);verifyAlbum(array_column($rows,'id')===array_column($old,'id')&&$rows[0]['caption']==='Caption','Stable IDs and metadata retained');
 validateAlbumReference($db,$photo,$album['id']);validateMilestonePhoto($db,$photo,'event',$album['id']);
